<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('inventory.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'inventory_stock');
if($_SERVER['REQUEST_METHOD']==='POST'){if(fpost('action')==='adjust'){$loc=fint('location_id');$mat=fint('material_id');$qty=fnum('quantity');$type=$qty>=0?'adjustment_in':'adjustment_out';$pdo->prepare('INSERT INTO inventory_stock(location_id,material_id,quantity_on_hand) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity_on_hand=quantity_on_hand+VALUES(quantity_on_hand)')->execute([$loc,$mat,$qty]);$pdo->prepare('INSERT INTO inventory_transactions(location_id,material_id,transaction_type,quantity,notes,performed_by) VALUES(?,?,?,?,?,?)')->execute([$loc,$mat,$type,abs($qty),fpost('notes')?:'Manual adjustment',current_staff()['id']]);flash('success','Inventory adjusted.');}staff_redirect('staff/pages/inventory.php');}
$locs=db_rows($pdo,'SELECT * FROM inventory_locations ORDER BY name');$mats=material_options($pdo);$rows=db_rows($pdo,'SELECT i.*,l.name location_name,m.material_code,m.name material_name,m.unit,m.minimum_stock_level,(i.quantity_on_hand-i.quantity_reserved) available FROM inventory_stock i JOIN inventory_locations l ON l.id=i.location_id JOIN materials m ON m.id=i.material_id ORDER BY m.name,l.name');$pageTitle='Inventory';require __DIR__.'/../../includes/staff/header.php';module_head('Operations','Inventory','See on-hand, reserved and usable materials by location.');?>
<section class="staff-panel"><h2>Stock adjustment</h2><form method="post" class="mini-form"><?=csrf_field()?><input type="hidden" name="action" value="adjust"><label>Location<select name="location_id"><?php foreach($locs as $l):?><option value="<?=$l['id']?>"><?=h($l['name'])?></option><?php endforeach?></select></label><label>Material<select name="material_id"><?php foreach($mats as $m):?><option value="<?=$m['id']?>"><?=h($m['name'])?></option><?php endforeach?></select></label><label>Quantity (+/-)<input type="number" step=".001" name="quantity" required></label><label>Reason<input name="notes"></label><button class="btn primary">Apply adjustment</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Material</th><th>Location</th><th>On hand</th><th>Reserved</th><th>Available</th><th>Stock health</th></tr></thead><tbody><?php foreach($rows as $r):$low=$r['available']<$r['minimum_stock_level'];?><tr><td><b><?=h($r['material_name'])?></b><small><?=h($r['material_code'])?></small></td><td><?=h($r['location_name'])?></td><td><?=$r['quantity_on_hand'].' '.h($r['unit'])?></td><td><?=$r['quantity_reserved']?></td><td><b><?=$r['available']?></b></td><td class="<?=$low?'danger-text':'success-text'?>"><?=$low?'Low stock':'OK'?></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>